CREATE TYPE source_health_state AS ENUM ('HEALTHY','DEGRADED','STALE','DISCONNECTED','BACKFILLING');
CREATE TABLE methodology_versions (id text PRIMARY KEY, kind text NOT NULL, status text NOT NULL, effective_from timestamptz NOT NULL, effective_to timestamptz, specification_uri text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO methodology_versions(id,kind,status,effective_from,specification_uri) VALUES ('COIP-1','PANEL','PROVISIONAL','2026-08-21','docs/methodology/coip.md'),('REF-JEFFREYS-1','REFERENCE_INDEX','PROVISIONAL','2026-08-21','docs/methodology/reference-index.md'),('EMOJI-17.0-CULT-V1','EXPRESSION_REGISTRY','ACTIVE','2026-08-21','config/expression-universe-v1.json') ON CONFLICT DO NOTHING;
CREATE TABLE source_watermarks (source_id text PRIMARY KEY, cursor text NOT NULL, last_event_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE source_health_snapshots (source_id text NOT NULL, observed_at timestamptz NOT NULL, state source_health_state NOT NULL, last_event_at timestamptz, last_receive_at timestamptz, stream_lag_ms bigint, events_per_minute bigint NOT NULL, parse_errors bigint NOT NULL, duplicate_events bigint NOT NULL, reconnect_count bigint NOT NULL, source_version text NOT NULL, PRIMARY KEY(source_id,observed_at));
CREATE INDEX source_health_latest_idx ON source_health_snapshots(source_id,observed_at DESC);
CREATE TABLE expression_observations_v2 (expression_id text NOT NULL, platform_id text NOT NULL, content_bucket text NOT NULL, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, eligible_documents bigint NOT NULL CHECK(eligible_documents>=0), expression_documents bigint NOT NULL CHECK(expression_documents BETWEEN 0 AND eligible_documents), occurrence_count bigint NOT NULL CHECK(occurrence_count>=expression_documents), unique_author_estimate bigint NOT NULL, raw_prevalence numeric(20,8) NOT NULL, smoothed_prevalence numeric(20,8) NOT NULL, largest_author_share numeric(12,10) NOT NULL, top_ten_author_share numeric(12,10) NOT NULL, effective_authors numeric(20,8) NOT NULL, source_health source_health_state NOT NULL, methodology_version text NOT NULL REFERENCES methodology_versions(id), source_version text NOT NULL, expression_registry_version text NOT NULL REFERENCES methodology_versions(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(expression_id,platform_id,content_bucket,window_start,methodology_version,source_version,expression_registry_version));
CREATE INDEX expression_observations_v2_time_idx ON expression_observations_v2(window_start DESC,platform_id,expression_id);
CREATE TABLE reference_index_snapshots (expression_id text NOT NULL, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, value numeric(20,8) NOT NULL, aggregate_log_return numeric(20,12) NOT NULL, is_final boolean NOT NULL DEFAULT false, status text NOT NULL, data_quality_score numeric(8,4), methodology_version text NOT NULL REFERENCES methodology_versions(id), source_version text NOT NULL, expression_registry_version text NOT NULL REFERENCES methodology_versions(id), revision_number integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(expression_id,window_start,methodology_version,source_version,expression_registry_version,revision_number));
CREATE UNIQUE INDEX one_active_official_close_idx ON reference_index_snapshots(expression_id,window_start,methodology_version,source_version,expression_registry_version) WHERE is_final AND status='OFFICIAL';
CREATE TABLE official_close_revisions (id uuid PRIMARY KEY, expression_id text NOT NULL, close_window_start timestamptz NOT NULL, original_value numeric(20,8) NOT NULL, revised_value numeric(20,8) NOT NULL, revision_number integer NOT NULL, revision_reason text NOT NULL, revised_at timestamptz NOT NULL DEFAULT now(), methodology_version text NOT NULL, source_version text NOT NULL, expression_registry_version text NOT NULL, UNIQUE(expression_id,close_window_start,methodology_version,source_version,expression_registry_version,revision_number));
ALTER TABLE indexes ADD COLUMN methodology_classification text NOT NULL DEFAULT 'CURATED' CHECK(methodology_classification IN ('CURATED','RULES_BASED','DATA_DRIVEN','EXPERIMENTAL'));
ALTER TABLE index_snapshots ADD COLUMN methodology_version text;
ALTER TABLE index_snapshots ADD COLUMN source_version text;
ALTER TABLE index_snapshots ADD COLUMN expression_registry_version text;
